import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.client.discovery.EnableDiscoveryClient;
import org.springframework.cloud.openfeign.EnableFeignClients;
import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.stereotype.Component;
import com.alibaba.csp.sentinel.annotation.SentinelResource;
import com.alibaba.csp.sentinel.slots.block.BlockException;

@SpringBootApplication
@EnableDiscoveryClient
@EnableFeignClients
public class OrderServiceApp {
    public static void main(String[] args) {
        SpringApplication.run(OrderServiceApp.class, args);
    }
}

@FeignClient(name = "user-service", fallback = UserClientFallback.class)
public interface UserClient {
    @GetMapping("/users/{id}")
    UserProfileDTO getUser(@PathVariable("id") String id);

    @PostMapping("/users/batch")
    List<UserProfileDTO> batchGetUsers(@RequestBody List<String> ids);
}

@Component
public class UserClientFallback implements UserClient {
    @Override
    public UserProfileDTO getUser(String id) {
        return UserProfileDTO.unknown(id);
    }

    @Override
    public List<UserProfileDTO> batchGetUsers(List<String> ids) {
        return Collections.emptyList();
    }
}

@Service
public class OrderQueryService {

    @SentinelResource(value = "orderQuery", blockHandler = "queryBlock")
    public OrderDTO query(String orderId) {
        OrderDTO local = orderRepo.findById(orderId);
        if (local == null) {
            return OrderDTO.empty(orderId);
        }
        UserProfileDTO user = userClient.getUser(local.getUserId());
        return local.attachUser(user);
    }

    public OrderDTO queryBlock(String orderId, BlockException ex) {
        return OrderDTO.empty(orderId);
    }
}
